#include "valid-c-prefix-fopen.test.h"

// ADR-046: Valid c_ prefix with fopen and fgets while loop
// cppcheck-suppress misra-c2012-21.6
#include <stdio.h>

#include <string.h>
#include <stddef.h>

char line[257] = "";

void readFile(void) {
    FILE* c_file = fopen("data.txt", "r");
    if (c_file != NULL) {
        const char* c_result = fgets(line, 257, c_file);
        while (c_result != NULL) {
            (void)printf("%s", line);
            c_result = fgets(line, 257, c_file);
        }
        (void)fclose(c_file);
    }
}
